"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[55194],{25421(e,t,o){o.r(t),o.d(t,{assets:()=>u,contentTitle:()=>s,default:()=>h,frontMatter:()=>i,metadata:()=>n,toc:()=>c});const n=JSON.parse('{"id":"general/jumpcloud-university-enhancements","title":"Jumpcloud University Enhancements","description":"By urvashi","source":"@site/docs/general/jumpcloud-university-enhancements.md","sourceDirName":"general","slug":"/general/jumpcloud-university-enhancements","permalink":"/jc-community-archive/general/jumpcloud-university-enhancements","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Jumpcloud University Enhancements","description":"By urvashi"},"sidebar":"docs","previous":{"title":"Jumpcloud Supports Searching For Microsoft Store Applications","permalink":"/jc-community-archive/general/jumpcloud-supports-searching-for-microsoft-store-applications"},"next":{"title":"Jumpcloud University Gets A Facelift","permalink":"/jc-community-archive/general/jumpcloud-university-gets-a-facelift-570"}}');var a=o(74848),r=o(28453);const i={title:"Jumpcloud University Enhancements",description:"By urvashi"},s=void 0,u={},c=[{value:"Overview",id:"overview",level:2},{value:"Transcript",id:"transcript",level:2},{value:"Q&amp;A",id:"qa",level:3}];function l(e){const t={a:"a",h2:"h2",h3:"h3",li:"li",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:["This is an edited transcript of the ",(0,a.jsx)(t.a,{href:"https://www.youtube.com/watch?v=yLAkskbSfnE",children:"05.10.24 IT Hour"})]}),"\n",(0,a.jsx)(t.h2,{id:"overview",children:"Overview"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Ella Rigoulot from the JumpCloud University team gives an update on the latest improvements to JumpCloud University"}),"\n",(0,a.jsxs)(t.li,{children:["Sign up for access to JumpCloud University here: ",(0,a.jsx)(t.a,{href:"https://university.jumpcloud.com/",children:"https://university.jumpcloud.com/"})]}),"\n"]}),"\n",(0,a.jsx)(t.h2,{id:"transcript",children:"Transcript"}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Ella"}),": I\u2019m going to talk about some specific enhancements. My team works extremely hard to work with people like Trevor when we come out with our content and our feature releases and product releases to make sure that our content is up to date, but it\u2019s a heavy task. I think I presented in December about a survey we did at the end of all of our courses and a lot of our feedback this last year was about \u201cwhere do we start as an organization\u201d, kind of making it a little bit clearer. So we listened to that and we developed some enhancements that I\u2019m going to walk through.\xa0"]}),"\n",(0,a.jsx)(t.p,{children:"We have these really great new self guided onboarding courses. These are awesome if you\u2019re implementing or self guiding or you have someone new at your company. Or if you\u2019re an MSP, a partner, you\u2019ve got somebody else coming on board, have them take a look at these onboarding courses. They really walk you through the steps to learn how to implement JumpCloud. The next thing we\u2019ve got is our featured content. So anytime we have new courses, we\u2019re going to have them in that featured content.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"One of the biggest things we listened to all of you about is the learning paths. They were a bit more focused a couple of years ago to where the product was at the time, so we\u2019ve adjusted them for areas of product focus. So we\u2019ve got the Foundations of JumpCloud which is brand new and kind of just \u201cWhat is JumpCloud\u201d courses. They\u2019re foundations of Open Directory, really great for new employees you might have coming in underneath you or at your company to learn about JumpCloud. Then we have focused courses on Identity Management and Device Management, Access and Resource Management. The areas of the product that you might be looking at or utilizing more, we\u2019ve put all of our courses that go around those topics, whether they\u2019re foundational or advanced, in those specific learning paths.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"Then of course we have our certifications. Our Core Certification learning path and the Advanced Certification learning path. Those are still the same. We\u2019re constantly maintaining these courses and updating them when there\u2019s releases and feedback. So if you took the certification in 2021, the questions are extremely different than now, so highly recommend that you guys take a look at those and update them and keep your certifications fresh.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"I\u2019m super big on hands-on learning and with my team I\u2019m always like \u201cHow can we encourage them to go into the product and now do this?\u201d and I would love to see us having a lab environment or a virtual machine where you can go in and practice. We\u2019re not there yet but it\u2019s something we would love to be able to do.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"Also when you go into My Dashboard now you can see visual progress. Like you can see that you\u2019ve passed a certification exam, but when it comes to the self guided onboarding path, you\u2019re only 35% complete so you can go back in and complete that. A lot of people weren\u2019t really sure which courses they\u2019ve completed and what the status was\xa0 so now you can see that visual. You can also see learning paths you\u2019re registered in, ones you have in progress and ones that are not started.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"Then we have this really great new search feature. So let\u2019s say you want something on Active Directory Integration, you can search for that. We\u2019ve also enhanced our Resources page. We\u2019ve got tutorials, simulations, and end user resources. So if you\u2019re an IT Admin and you want to train your end users on how to use JumpCloud and the User Console, we\u2019ve got a lot of information here. You have a visual here of a yellow person, that means it\u2019s end user content, so you can show it to your end users or put it in an onboarding plan.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"We\u2019ve also integrated our Help Center. So you can see Help Center articles here, you don\u2019t have to go to support.jumpcloud.com to find those. So you can search and filter by types of content and by topics to find exactly what you\u2019re looking for.\xa0"}),"\n",(0,a.jsx)(t.h3,{id:"qa",children:"Q&A"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"Q: How do we renew our certifications?"})}),"\n",(0,a.jsx)(t.p,{children:"A: We don\u2019t have a full renewal certificate just yet. We didn\u2019t have an audit process in place to ensure we were updating our certifications effectively but now that that\u2019s in place you\u2019ll probably start seeing more renewal information and recommendations for renewal. We do recommend that you retake our certifications every two years but the renewal process and a clear strategy for that will come out next year.\xa0"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"Q: Do certifications expire and is there a plan to have them expire at some point?"})}),"\n",(0,a.jsx)(t.p,{children:"A: They\u2019ll probably expire about every two years starting in 2025.\xa0"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"Q: Do you have to complete the Core Certification before you can attempt the Advanced Certification?"})}),"\n",(0,a.jsx)(t.p,{children:"A: You do not. If you\u2019ve been using JumpCloud for a while and you\u2019re really deep into it, go ahead and take the Advanced practice exam. But if you\u2019re just getting started then do the core foundational courses, get your core assessment, continue to use JumpCloud and then you can take a look at those advanced topics.\xa0"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"Q: Is the Advanced Certification worth it because by that point you\u2019re knee deep into the topics and can read the specifics when needed?"})}),"\n",(0,a.jsx)(t.p,{children:"A: I think it is. JumpCloud is gaining more and more clients and I think that the skill set and being able to showcase your skill set by showing you\u2019re certified, you\u2019ve passed the assessment, is worth it. All of our learning is free but if you want to showcase your skill set, talk to other employers, move to other companies that might use JumpCloud, having the Advanced Certification gives you that level up. Especially if you\u2019re a partner and want to showcase those skill sets to your clients. If you\u2019re working a helpdesk, having the Advanced Certification is a great way to say \u201cHey I know this off the top of my head. I don\u2019t have to go in and look it up. I can get those tickets cleared up sooner than later.\u201d"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"Q: Are the certifications available on Credly?"})}),"\n",(0,a.jsxs)(t.p,{children:["A: Yes they are. If you\u2019ve taken the exam and haven\u2019t received an email about it please reach out to ",(0,a.jsx)(t.a,{href:"https://web.archive.org/web/20250911082343/mailto:university@jumpcloud.com",children:"university@jumpcloud.com"})," and we\u2019ll make sure we get that awarded to you."]})]})}function h(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},28453(e,t,o){o.d(t,{R:()=>i,x:()=>s});var n=o(96540);const a={},r=n.createContext(a);function i(e){const t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);